/**
 * Wire-shape types for the platform's table endpoints.
 *
 * Mirrors the platform table wire schemas:
 *   - TableCreateRequest
 *   - TableUpdateRequest
 *   - Table
 *   - TablePagedList
 *
 * The shapes here are the literal JSON payload — the serializer in
 * `src/tables/serializer/` resolves EDK refs (App / Element /
 * AspectCategoryRef / CloudLink / built TableField factory output)
 * to id-strings and discriminated objects the platform request expects.
 */
import type { DeployResponse } from "../../../types.js";
export type AspectFieldSemanticTag = "ASSIGNEE" | "ASSIGNMENT_GROUP" | "BREAK_LINE" | "CLOSED_AT" | "CLOSED_BY" | "COST" | "CREATED_AT" | "CREATED_BY" | "CURRENCY" | "DESCRIPTION" | "DUE_DATE" | "FULL_LINE" | "HANDLE" | "PERCENT" | "PERCENT_MULTIPLY" | "PRIORITY" | "REVENUE" | "STAGE" | "STATUS" | "TITLE" | "TOTAL_VALUE_MANAGED" | "UPDATED_AT" | "UPDATED_BY" | "VERSION";
export type AspectFieldType = "ATTACHMENT_ID" | "BOOLEAN" | "DATE" | "DATETIME" | "DECIMAL" | "GROUP_ID" | "HANDLE" | "HTML" | "JSON" | "MULTI_PICKLIST" | "NUMBER" | "PICKLIST" | "TEXT" | "USER_ID";
export type TableFieldAggregation = "AVERAGE" | "COUNT" | "COUNT_DISTINCT" | "MAX" | "MIN" | "NOT_SET" | "STANDARD_DEVIATION" | "SUM";
export type TableFieldExpanded = "GROUP_NAME" | "MULTI_PICKLIST_LABEL" | "PICKLIST_LABEL" | "STAGE_NAME" | "USER_EMAIL" | "USER_FIRST_NAME" | "USER_LAST_NAME";
export type TableJoinType = "FULL" | "INNER" | "LEFT" | "RIGHT";
export interface TableFieldSnowflakeInput {
    readonly columnName: string;
    readonly type: AspectFieldType;
}
export interface TableFieldBigQueryInput {
    readonly columnName: string;
    readonly type: AspectFieldType;
}
export interface TableFieldCloudCreateInput {
    readonly name: string;
    readonly snowflake?: TableFieldSnowflakeInput;
    readonly bigQuery?: TableFieldBigQueryInput;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export interface TableCalculationCreateInput {
    readonly name: string;
    readonly text: string;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export interface TableFieldAggregatableCreateInput {
    readonly name: string;
    /** Source field id (a TableField on this or a related table). */
    readonly field: string;
    readonly aggregation?: TableFieldAggregation;
    readonly expanded?: TableFieldExpanded;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
/**
 * Discriminated field input — populate exactly one of `cloud`,
 * `calculation`, or `reference`. The platform validates this at the
 * server boundary; the SDK serializer enforces it locally so the
 * compiler catches misuse.
 */
export interface TableFieldCreateInput {
    readonly cloud?: TableFieldCloudCreateInput;
    readonly calculation?: TableCalculationCreateInput;
    readonly reference?: TableFieldAggregatableCreateInput;
}
export interface TableFieldCloudUpdateInput {
    readonly name: string;
    readonly snowflake?: TableFieldSnowflakeInput;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export interface TableCalculationUpdateInput {
    readonly name?: string;
    readonly text?: string;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export interface TableFieldAggregatableUpdateInput {
    readonly name?: string;
    readonly field?: string;
    readonly aggregation?: TableFieldAggregation;
    readonly expanded?: TableFieldExpanded;
    readonly tags?: readonly AspectFieldSemanticTag[];
}
export interface TableFieldUpdateInput {
    readonly cloud?: TableFieldCloudUpdateInput;
    readonly calculation?: TableCalculationUpdateInput;
    readonly reference?: TableFieldAggregatableUpdateInput;
}
export interface TableFieldIdentityInput {
    readonly id: string;
    readonly clientHandle?: string;
    readonly __typename?: string;
}
export interface TableFieldEnvelopeUpdateInput {
    readonly id?: string;
    readonly name?: string;
    readonly fieldType?: AspectFieldType | string;
    readonly tags?: readonly string[];
    readonly semanticTags?: readonly string[];
    readonly field?: TableFieldIdentityInput;
    readonly source?: TableFieldIdentityInput;
    readonly clientHandle?: string;
    readonly isAggregated?: boolean;
    readonly configured?: boolean;
    readonly __typename?: string;
    readonly cloud?: TableFieldCloudUpdateInput;
    readonly calculation?: TableCalculationUpdateInput;
    readonly reference?: TableFieldAggregatableUpdateInput;
    readonly aggregation?: TableFieldAggregation;
    readonly expanded?: TableFieldExpanded;
}
export type TableFieldUpdatePayload = TableFieldUpdateInput | TableFieldEnvelopeUpdateInput;
export interface TableFieldsV3UpdateCreateInput {
    readonly field: TableFieldCreateInput;
    readonly index?: number;
}
export interface TableFieldsV3UpdateSetInput {
    readonly id: string;
    readonly field: TableFieldUpdatePayload;
    readonly index?: number;
}
export interface TableFieldsV3UpdateDeleteInput {
    readonly id: string;
}
export interface TableFieldsV3UpdateInput {
    readonly creates?: readonly TableFieldsV3UpdateCreateInput[];
    readonly updates?: readonly TableFieldsV3UpdateSetInput[];
    readonly deletes?: readonly TableFieldsV3UpdateDeleteInput[];
}
export interface TableJoinFieldInput {
    /** Field id on the parent (host) table side of the join. */
    readonly leftFieldId: string;
    /** Field id on the joined-in (source) table side of the join. */
    readonly rightFieldId: string;
}
export interface TableJoinInput {
    readonly source: string;
    readonly type: TableJoinType;
    readonly joinOn: readonly TableJoinFieldInput[];
    readonly filter?: unknown;
}
export interface TableSnowflakeMappingInput {
    readonly databaseName: string;
    readonly schemaName: string;
    readonly tableName: string;
}
export interface TableBigQueryMappingInput {
    readonly datasetName: string;
    readonly tableName: string;
}
export interface TableDatabricksMappingInput {
    readonly databaseName: string;
    readonly schemaName: string;
    readonly tableName: string;
}
export interface TableCloudMappingInput {
    readonly cloudLinkId: string;
    readonly snowflakeMapping?: TableSnowflakeMappingInput;
    readonly bigQueryMapping?: TableBigQueryMappingInput;
    readonly databricksMapping?: TableDatabricksMappingInput;
}
export interface TableDataViewSnowflakeCreateInput {
    readonly databaseName: string;
    readonly schemaName: string;
    readonly name: string;
}
export interface TableDataViewCreateInput {
    readonly snowflake?: TableDataViewSnowflakeCreateInput;
}
export interface TableDataViewSnowflakeUpdateInput {
    readonly databaseName?: string;
    readonly schemaName?: string;
    readonly name?: string;
}
export interface TableDataViewUpdateInput {
    readonly snowflake?: TableDataViewSnowflakeUpdateInput;
}
/** Body for creating a table. */
export interface TableCreateRequest {
    readonly name: string;
    /** Record-handle prefix (e.g. "TKT"). */
    readonly handle: string;
    /** Source aspect (App / Element) id, or another Table id. */
    readonly source: string;
    /** AspectCategory id this table files under. */
    readonly categoryId: string;
    readonly fields: readonly TableFieldCreateInput[];
    readonly description?: string;
    readonly icon?: string;
    readonly color?: string;
    readonly cloudMapping?: TableCloudMappingInput;
    readonly dataView?: TableDataViewCreateInput;
    readonly join?: TableJoinInput;
    readonly joins?: readonly TableJoinInput[];
    /** Opaque Filter JSON applied to the table results. */
    readonly filter?: unknown;
    /** Opaque Limit JSON. */
    readonly limit?: unknown;
    /** Opaque Sort JSON. */
    readonly orderBy?: unknown;
}
/** Body for updating a table. */
export interface TableUpdateRequest {
    readonly name?: string;
    readonly source?: string;
    readonly categoryId?: string;
    readonly description?: string;
    readonly icon?: string;
    readonly color?: string;
    readonly fields?: TableFieldsV3UpdateInput;
    readonly cloudMapping?: TableCloudMappingInput;
    readonly dataView?: TableDataViewUpdateInput;
    readonly filter?: unknown;
    readonly limit?: unknown;
    readonly orderBy?: unknown;
}
/**
 * Response field shape — narrow union that mirrors what the platform
 * surfaces today on `Table.fields[]`. Each variant carries the same
 * identity surface (`id`, `name`, `fieldType`, `tags`,
 * `semanticTags`); per-variant slots round-trip extra metadata.
 */
export interface TableFieldWire {
    readonly id: string;
    readonly name: string;
    readonly fieldType: AspectFieldType;
    readonly configured?: boolean;
    readonly isAggregated?: boolean;
    readonly tags?: readonly string[];
    readonly semanticTags?: readonly AspectFieldSemanticTag[];
    /** Discriminator surfaced by the platform on each variant. */
    readonly __typename?: string;
    /** Extra metadata passes through opaquely. */
    readonly [key: string]: unknown;
}
export interface TableJoinWire {
    readonly id: string;
    readonly type?: TableJoinType;
    readonly [key: string]: unknown;
}
/** Trimmed Table response. The platform returns more; we project to id + the bits the SDK needs. */
export interface TableWire {
    readonly id: string;
    readonly name: string;
    readonly handle: string;
    readonly type?: string;
    readonly configured?: boolean;
    readonly editable?: boolean;
    readonly cloudManaged?: boolean;
    readonly fields?: readonly TableFieldWire[];
    readonly joins?: readonly TableJoinWire[];
    readonly __typename?: string;
    readonly [key: string]: unknown;
}
/**
 * Normalized deploy response. Matches the `DeployResponse` contract
 * (a top-level `id`) so the late-binding registry and per-process
 * stamp WeakMap key uniformly across entity kinds.
 */
export interface DeployedTable extends DeployResponse {
    readonly id: string;
    readonly name?: string;
    readonly handle?: string;
    readonly __typename?: string;
}
/** Trimmed page shape for `GET /tables`. */
export interface TablePagedList {
    readonly items: readonly TableWire[];
    readonly paging?: {
        readonly has_next_page?: boolean;
        readonly end_cursor?: string;
    };
}
